use std::collections::BTreeSet;
use std::fs;
use std::path::Path;

const FOLD: &str = include_str!("../foldrib/rim.rs");
const POOL: &str = include_str!("../internpit/pool.rs");
const INK: &str = include_str!("../restcue/ink.rs");
const BOOT: &str = include_str!("../steerpit/boot.rs");
const HEARTH: &str = include_str!("hearth.rs");
const MAIN: &str = include_str!("main.rs");

fn put(path: &str, body: &str) -> Result<(), ()> {
    fs::write(path, body).map_err(|_| ())
}

pub fn rib_d() -> i32 {
    let mut cards = match fs::read_dir("/app/daycards") {
        Ok(v) => v.filter_map(Result::ok).map(|e| e.path()).collect::<Vec<_>>(),
        Err(_) => return 1,
    };
    cards.sort();
    let mut emits = BTreeSet::new();
    for card in cards {
        if !card.is_file() {
            continue;
        }
        let text = match fs::read_to_string(&card) {
            Ok(v) => v,
            Err(_) => return 1,
        };
        for line in text.lines().map(str::trim).filter(|s| !s.is_empty() && !s.starts_with('#')) {
            let mut words = line.split_whitespace();
            if words.next() != Some("emit") {
                return 1;
            }
            let Some(piece) = words.next() else { return 1; };
            if words.next().is_some() {
                return 1;
            }
            emits.insert(piece.to_string());
        }
    }

    let tree = match fs::read_to_string("/app/vatslip/TREE.txt") {
        Ok(v) => v,
        Err(_) => return 1,
    };
    let names: BTreeSet<&str> = tree.lines().map(str::trim)
        .filter(|s| !s.is_empty() && !s.starts_with('#')).collect();
    let required = ["foldrib", "internpit", "restcue", "emitbay", "steerpit"];
    if required.iter().any(|name| !names.contains(name)) {
        return 1;
    }
    if !emits.contains("freeze") || !emits.contains("cells") {
        return 1;
    }

    let writes = [
        ("/app/foldrib/rim.rs", FOLD),
        ("/app/internpit/pool.rs", POOL),
        ("/app/restcue/ink.rs", INK),
        ("/app/emitbay/hearth.rs", HEARTH),
        ("/app/emitbay/main.rs", MAIN),
        ("/app/steerpit/boot.rs", BOOT),
    ];
    for (path, body) in writes {
        if !Path::new(path).parent().is_some_and(Path::is_dir) || put(path, body).is_err() {
            return 2;
        }
    }
    0
}
